INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Objectives`, `Details`, `Objectivetext1`, `Objectivetext2`, `Objectivetext3`, `Objectivetext4`, `VerifiedBuild`) VALUES
(25249,'koKR','마음 바꾸기',NULL,NULL,NULL,NULL,NULL,NULL,0),
(25283,'koKR','연설 준비','노움 재생 장치를 카라노스 북쪽에 있는 오지 토글볼트, 스틸그릴의 정비소에 있는 밀리 페더휘슬, 카라노스 여관 밖에 있는 토그 러스츠프로켓에게 사용해야 합니다. 연설을 모두 들려준 뒤 토비 자이기어에게 가야 합니다.','멕카토크 왕께서 전쟁 시작 전에 연설할 때 쓰일 연설문을 써 달라고 요청하셨어요. 그런데 저는 어떤 연설문이 더 좋고 나쁜지 더는 모르겠네요.$b$b이 연설문들을 놈리건 주민이 있는 곳에 가져가서 시험해줄 수 있나요? 이 장치는 멕카토크 왕의 영상을 만들어 내가 쓴 여러 개의 연설문 중에서 몇 줄씩 말하게 해줄 거예요.$b$b어떤 연설문이 제일 효과적인지 말해 주세요, 알겠죠?','오지 토글볼트에게 연설문 들려주기','밀리 페더휘슬에게 연설문 들려주기','토그 러스츠프로켓에게 연설문 들려주기',NULL,0),
(25285,'koKR','사출 좌석 시험','탈출형 기계보행전차의 사출 좌석을 시험해야 합니다.','이 전차들을 공격 작전에 사용할 수 있게 점검해야 하네. 이놈들을 시험할 준비는 되었나? 물론 그래야지!$b$b첫 번째로 이 전차로 들어가 탈출할 수 있는지 시험해야 하네. 만약 전투 중에 전차가 폭발할 것 같다면 바로 빠져나와야 하니 말일세! 많은 노움들이 전차가 폭발할 때까지 있다가 쓰디쓴 최후를 맞는 것을 봐 왔네. 전차가 폭발하면 그 안의 충격으로 가루가 돼버리는 거지... 어쨌든 전차에 사출 좌석을 새로 장착했네. 한번 시험해 보겠나?','사출 좌석 시험하기',NULL,NULL,NULL,0),
(25286,'koKR','연설문 전달','스틸그릴의 정비소에 있는 대장 트레드 스파크노즐에게 연설문을 전달해야 합니다.$b$b제공된 아이템: $b','자, 여기 연설문이 있어요, $n!$b$b전쟁을 알리는 멋진 신호탄이 될 거예요. 영감적이고, 훌륭한 말솜씨로 노움들의 마음에 용기를 북돋아주는 거예요. 이것보다 훌륭한 연설문은 써본 적이 없을 정도에요!$b$b대장 트레드 스파크노즐에게 전달해 땜장이왕 멕카토크에게 갈 이동 수단을 찾아보세요!',NULL,NULL,NULL,NULL,0),
(25287,'koKR','연설문 전달','스틸그릴의 정비소 밖에 있는 ''천둥번개''를 타고 땜장이왕 멕카토크에게 토비의 연설문을 가져가야 합니다.','좋아, 병사! 이제 자네의 능력을 보여줄 때군!$b$b이 연설문을 가지고 ''천둥번개''에 타게. 땜장이왕 멕카토크에게 가장 빨리 갈 수 있는 비행기이네. 멕카토크는 놈리건 작전이 시작되기 전에 이 연설문이 오기만을 애타게 기다리고 있네.$b$b서두르게!',NULL,NULL,NULL,NULL,0),
(25289,'koKR','일보 앞으로...','기동형 기계보행전차의 기동성을 시험해야 합니다.','사출 좌석이 잘 작동하니까, 이제 기동에 관한 시험을 해봐야겠군. 이 전차는 아주 특별한 기능을 가지고 있네. 바로 교묘한 회피 기능이지!$b$b왼쪽과 오른쪽 다리 제어장치 작동 여부와 교묘한 회피 기능을 시험해 주게.$b$b쉬운 일이니까 그렇게 오래 걸리지는 않을 것이네.','왼쪽 다리 제어장치 시험하기','오른쪽 다리 제어장치 시험하기','교묘한 회피 기능 시험하기',NULL,0),
(25295,'koKR','속사포 시험','가까운 표적에 공격형 기계보행전차의 속사포를 시험해야 합니다.','안전 시스템, 작동 중!, 모터 기능, 이상 없음! 이제 속사포 발사 시험만 남았군.$b$b아주 어려운 건 아닐세, $n. 뒤쪽 언덕에 있는 기계보행전차에 인체에 무해한 탄알을 장전했으니까 주변 표적에 몇 발 쏘고 난 뒤 다시 이리로 오게.','속사포 시험하기',NULL,NULL,NULL,0),
(25393,'koKR','놈리건 작전','멕카토크 왕을 도와 놈리건을 되찾아야 합니다.','이제 곧 놈리건에 파상 공격이 시작되면 기계박사 텔마플러그와 그의 수하들은 정의의 심판을 받게 될 것일세! 기계박사 텔마플러그는 썩어빠지고 더러운 그의 수하들과 함께 너무나 긴 시간 동안 우리의 고향을 더럽혀 왔네.$b$b공격이 곧 시작될 테니 준비하게, 신병! 비겁자는 용서할 수 없네!',NULL,NULL,NULL,NULL,0),
(25445,'koKR','잘라제인의 최후','볼진이 메아리 섬을 되찾고 잘라제인을 처치하도록 도와야 합니다.','이제 전쟁이네! 곧 메아리 섬으로 진격할 테니 준비를 단단히 해 두게.$b$b잘라제인이 살 날도 얼마 남지 않았네.','잘라제인 처치',NULL,NULL,NULL,0),
(25446,'koKR','개구리 투하!','박쥐를 타고 가는 동안 개구리 자루에 있는 주문에 걸린 개구리 12마리를 메아리 섬에 표시된 지역에 던져 넣어야 합니다.','개구리가 준비됐으니, 이제 이걸 섬으로 보내게 도와주세요.$b$b센진 마을에서 동쪽으로 가면 조련사 만렉을 만날 수 있을 거예요. 만렉은 볼진 정찰대가 사용하는 모든 박쥐를 관리하고 있으니까 메아리 섬에 갈 박쥐를 빌릴 수 있을 거예요.$b$b이 개구리 자루를 가지고 가세요. 정령들의 가호를 요청했더니 제 눈으로 봐야 할 곳을 그대에게 보여주려고 연기를 보내 줬어요. 박쥐를 타고 가는 동안 자루 안의 개구리를 꺼내 그 연기 안으로 던져 넣으면 돼요.','주문에 걸린 개구리 보내기',NULL,NULL,NULL,0),
(25461,'koKR','트롤 지원병 모집','볼진의 전쟁 북을 이용해 칼바위 언덕에서 트롤 시민 5명을 모집해야 합니다.$b$b조련사 만렉과 대화하면 칼바위 언덕으로 가는 박쥐를 탈 수 있습니다.','볼진 님께서 내게 전쟁 북과 신입 트롤을 훈련시킬 권한을 주셨네. 신입 트롤이 부족한 게 문제지만 말일세.$b$b이 북을 그대에게 빌려주면 칼바위 언덕에서 볼진 진영의 전쟁을 알리는 북소리를 내줄 수 있겠나? 적은 수의 트롤이라도 자원한다면 전쟁에 큰 도움이 될 걸세. 트롤을 모집하면 훈련을 위해 이곳으로 돌아오게. 남쪽에 있는 조련사 만렉에게 이야기하면 칼바위 언덕까지 가는 박쥐를 탈 수 있을 것이네.','트롤 시민','트롤 시민','트롤 지원병','트롤 지원병',0),
(25470,'koKR','호랑이 여인','호랑이의 혼을 받은 동안 은신처에서 우두머리 암호랑이를 유인해낸 다음, 새로운 능력을 사용해 전투에서 승리해야 합니다.','제 눈과 귀 노릇을 하게 만들었던 개구리 기억나나요? 아무튼, 그 친구들이 흥미있는 걸 찾아냈어요.$b$b섬 남동쪽에서 다른 호랑이들도 무서워하는 듯한 호랑이를 염탐한 정보를 들었는데, 이런 호랑이는 이전에 본 적이 없어요.$b$b야수의 본능으로 사냥하면서도 인간의 지성을 가지고 있다고 하네요. 아마 그 호랑이는 강력한 영혼이자 아군일 수도 있을 거예요.$b$b그대에게 호랑이의 혼을 불어넣어 줄 테니 이 능력을 이용해 그 호랑이를 찾아 도전해보세요. 그대가 승리해 그 호랑이가 이 섬을 되찾기 위한 우리의 전쟁을 도와줄지 지켜보겠어요.','우두머리 암호랑이에게 도전하기',NULL,NULL,NULL,0),
(25480,'koKR','영혼의 춤','센진 마을 바깥에서 의식 무용수의 원 근처에 있는 의술사 헤즈톡과 대화해야 합니다.','행동을 개시할 시기를 결정할 때가 왔네. 용사 우루진이 이야기하길 다른 부하들도 준비가 되었다고 하더군. 자네와 바니라 덕분에 적의 정보를 잘 수집했을 뿐 아니라 새로운 아군도 발견했네.$b$b이제 점을 쳐봐야 해. 공격을 시작할 시기를 정해야지.$b$b의식 무용수의 원 근처에서 의술사 헤즈톡을 찾게. 자네가 준비되는 대로 곧 의식을 시작할 걸세.','영혼의 춤',NULL,NULL,NULL,0),
(25495,'koKR','전투 준비','조련사 만렉과 대화하고 집결지로 날아가십시오. 전투 야영지 동쪽에 있는 섬에서 볼진을 만나야 합니다.','볼진 님은 군 장비와 전사들을 모으고 계시네. 자네보고 바니라와 함께 동쪽 섬에서 만나자고 전해 달라시더군.$b$b볼진 님과 전사들은 그곳에서 잘라제인에 대한 공격을 개시할 걸세. 선조들이 항상 함께하길 비네, $n. 자네가 없었다면 이 작전이 이렇게까지 성공적이지는 않았을 걸세. 남쪽으로 가서 조련사 만렉을 만나보게. 집결지까지 태워줄 박쥐를 내줄 걸세.',NULL,NULL,NULL,NULL,0),
(25500,'koKR','연설문 전달','스틸그릴의 정비소에 있는 대장 트레드 스파크노즐에게 연설문을 전달해야 합니다.','자, 여기 연설문이 있어요, $n!$b$b전쟁을 알리는 멋진 신호탄이 될 거예요. 영감적이고, 훌륭한 말솜씨로 노움들의 마음에 용기를 북돋아주는 거예요. 이것보다 훌륭한 연설문은 써본 적이 없을 정도에요!$b$b대장 트레드 스파크노즐에게 전달한 뒤 그가 필요한 게 뭔지 알아보세요.',NULL,NULL,NULL,NULL,0),
(26012,'koKR','고룡쉼터의 골칫거리','용의 안식처에 있는 고룡쉼터 사원에서 크라서스와 대화해야 합니다.','옛 친구 크라서스가 용의 안식처에 있는 고룡쉼터에서 무시무시한 일이 벌어졌다는 소식을 전해왔소. 서신은 짤막했지만, 사원 아래에 있는 루비 성소에 모종의 공격이 있었음이 분명했소.$b$b여기 달라란의 일이 다망하여 직접 찾아가볼 수 없는 상황인데, 당신이 리치 왕의 성채에서 세웠던 혁혁한 공적 이야기를 들었소. 이 임무에 당신이 적합하다는 데에 일말의 의심도 없소만, 나를 대신하여 크라서스를 도와줄 수 있겠소?',NULL,NULL,NULL,NULL,0),
(26013,'koKR','공격받은 성소','고룡쉼터 사원 아래에 있는 루비 성소를 조사해야 합니다.','$r|1이여;여;, 사원 아래에 있는 루비 성소 안에서 무언가 끔찍한 일이 일어났다.$b$b성소로 가는 입구는 폐허가 되었고, 수호자들은 무참히 살해되었다. 상황을 알아보려 정찰병을 보냈지만, 돌아오지 않았다. 최악의 사태를 짐작하는 수밖에 없는 실정이다.$b$b루비 성소로 들어가 우리 용군단의 고향에 무슨 일이 일어났는지 밝혀줬으면 한다. 정보가 좀 더 있다면 그에 맞춰 어떤 행동을 취할지 계획을 세울 수 있으리라.',NULL,NULL,NULL,NULL,0);
